import{I as a}from"./patterns-widget-builder-DnOu3gnB.js";import{I as i}from"./patterns-trace-C_N42cH9.js";import"./index-B0WjJBI_.js";import"./_commonjsHelpers-CqkleIqs.js";import"./index-x-G-dxfr.js";import"./index-CwPCC0ZT.js";const n=a.find(s=>s.name==="Pattern: Report widgets — resize, drag & drop rules"),m={title:"Examples/Widget builder/Report widgets — resize, drag & drop rules",component:i["Pattern: Report widgets — resize, drag & drop rules"],tags:["autodocs","needs-review"],parameters:{docs:{description:{component:'> ⚠️ **Needs review** — check these against Figma:\n>\n> - Two charts in one row: the old frame 331:507955 shows a resize handle between them; the rules (413:56466) lock them at ½ + ½. The kit locks them (notes win).\n\n**Figma:** Page / 1 · Drag a widget into a row of 2 [patterns] (413:45297)\n\n## Widget builder pattern\n\n\n**For:** a page of widgets people arrange: add from a catalog, reorder by drag, resize on a 3-column grid, remove. A dashboard (widgets on the page, one grid) or a report (blocks inside sections, one grid per section); same widgets and rules. Editing only while the page is in Draft.\n\n**Parts:** `AppShell` + `NavBar` + `SideNav` + `PageHeader` + `BottomSheet type="documents"` (optional `Panel`) · page intro with a secondary "Widgets" button · `StatCardsRow` (the metrics block) · `WidgetBoard` (grid engine) of `WidgetFrame`s (the chart card header, rule 10.2: title, hover 6-dot handle, "Edit with Cooper", ⋯ menu) with kit charts inside (`bare`) · drag feedback: ghost (`WidgetFrame state="ghost"`, or `WidgetCard state="drag"` from the drawer), source at 30%, `DropIndicator`, then `DropZone` "+ Drop here to place", `Tooltip` for a blocked drop · resize: `ResizeHandle`, `Tooltip` · `WidgetsDrawer` (`Drawer` + search + `WidgetCard`s with `PreviewWidgetCard`) · `toast` + Undo.\n\n**Rules:**\n\n1. A section is a 3-column grid with a page gap (rule 3.14); widths only 1/3, 1/2, 2/3 or 3/3. A row holds 1–3 widgets, never spans sections, never leaves an empty column (the last widget fills the rest), and its widgets share the tallest height (height is never resized by hand).\n\n2. Auto widths: 1 → 3/3; 2 → 1/2 + 1/2; 3 → 1/3 each; chart + text → 2/3 + 1/3; chart + chart → 1/2 + 1/2, locked. A row of 2 may be 1/2 + 1/2, 1/3 + 2/3 or 2/3 + 1/3. Manual widths last until the count or order changes or the divider is double-clicked (→ Auto). Width is saved with the edition, the same for everyone.\n\n3. Limits: metrics block (1–3 stat cards of equal width) 3/3 only, no handle, not draggable; text 1/3–3/3; chart min 1/2, resizable only next to a text widget; wide chart or table 3/3 (proposed in Figma).\n\n4. Add: Widgets → drawer (`push`) → "+ Add" places the widget and removes its card, toast `"<name>" widget added` + Undo; or drag the card in (the drawer steps aside). The drawer search filters by description; no match → empty state.\n\n5. Move: drag from the whole header (rule 10.2; the 6-dot handle shows on hover; buttons excluded; starts after ~4px, a click doesn\'t; decided Nov 25, the `WidgetFrame` code still drags from ⋮⋮ with a ⋮ menu until the pattern is rebuilt in phase 2) → ghost follows, source fades → indicator line (vertical in a row = insert, horizontal between rows = new row; nothing moves) → resting ~300ms or hovering the line opens the zone at final size and the row reflows to Auto (a new-row zone is full width at the dragged widget\'s height; a taller widget grows the row; moving away collapses it) → release. Ghost and zone always show together. Toast `"<name>" widget moved` / "Block moved" + Undo. Report blocks can move between sections.\n\n6. Blocked drops (no line, no slot, tooltip): full row ("Row is full — max 3 widgets", "Row is full — max 2 widgets with a chart"), the min doesn\'t fit, or next to metrics ("Metrics take the whole row"); then only the lines above and below are targets. On release source and target rows go Auto; an empty row disappears; ~200ms animation.\n\n7. Resize: a handle on edge hover only (8 hit zone each side), never in the ~40 header zone; the hovered widget keeps its Hover actions, and resizing switches it to Drag state and hides them; arrows show only possible directions (none → no handle, default cursor); a divider is shared (the start widget\'s width, the other takes the rest); no handle on the first widget\'s start edge; the section\'s end edge only shrinks; chart rows have no edge handles. Past a limit: "Maximum / Minimum width reached" in a tooltip above the handle, without cancelling. Release snaps to the nearest step (under half a step → back). Double-click the divider → Auto. Also ⋯ → Resize → S (1/3) / M (2/3) / L (3/3) with the same limits.\n\n8. Widening pushes neighbours that no longer fit to the next row (or a new row); shrinking pulls the next widget up if its min fits, otherwise (last in the section, or the next is a chart) the widget can\'t shrink; charts never move rows by a resize.\n\n9. Remove: ⋯ → Remove (the code still shows ⋮ until phase 2), the row reflows, toast `"<name>" widget removed` + Undo (toasts: rule 14.12). Esc or releasing outside a target cancels (ghost flies back, no toast); Esc during a resize restores widths.'}},design:{type:"figma",url:"https://www.figma.com/design/KmmVU2D0kqWr0dC1xXNzWw/IFS-Design-System-Patterns?node-id=413-45297"},layout:"fullscreen"}},e={name:"All variants & states",render:()=>n.render()};var t,r,o;e.parameters={...e.parameters,docs:{...(t=e.parameters)==null?void 0:t.docs,source:{originalSource:`{
  name: 'All variants & states',
  render: () => section.render()
}`,...(o=(r=e.parameters)==null?void 0:r.docs)==null?void 0:o.source}}};const p=["AllVariants"];export{e as AllVariants,p as __namedExportsOrder,m as default};
